namespace Archy.Features.Placement.ScorePlacementOverlap;
/// <summary>Ranks module placement by confidence-weighted existing dependencies and explicitly abstains on weak or ambiguous evidence.</summary>
public sealed class PlacementOverlapScorer : IPlacementOverlapScorer
{
 public PlacementRecommendation Score(IReadOnlyList<PlacementDependency> dependencies,IReadOnlyList<PlacementClusterCandidate> clusters){ArgumentNullException.ThrowIfNull(dependencies);ArgumentNullException.ThrowIfNull(clusters);if(dependencies.Count==0||clusters.Count==0||dependencies.Any(d=>d is null||string.IsNullOrWhiteSpace(d.TargetStableId)||!double.IsFinite(d.Confidence)||d.Confidence is <0 or >1)||clusters.Any(c=>c is null||string.IsNullOrWhiteSpace(c.ClusterKey)||c.MemberStableIds is null)||clusters.Select(c=>c.ClusterKey).Distinct(StringComparer.Ordinal).Count()!=clusters.Count)throw new ArgumentException("Placement scoring requires valid dependencies and uniquely named clusters.");var total=dependencies.Sum(d=>d.Confidence);if(total==0)return new(true,"No dependency confidence is available.",[]);var scores=clusters.Select(c=>{var members=c.MemberStableIds.ToHashSet(StringComparer.Ordinal);var matched=dependencies.Where(d=>members.Contains(d.TargetStableId)).Sum(d=>d.Confidence);return new PlacementScore(c.ClusterKey,Math.Round(matched/total,6,MidpointRounding.AwayFromZero),matched,total,dependencies.Count(d=>members.Contains(d.TargetStableId)));}).OrderByDescending(s=>s.WeightedOverlap).ThenBy(s=>s.ClusterKey,StringComparer.Ordinal).ToArray();var best=scores[0];var ambiguous=scores.Length>1&&best.WeightedOverlap-scores[1].WeightedOverlap<.15d;return new(best.WeightedOverlap<.5d||ambiguous,best.WeightedOverlap<.5d?"Dependency overlap is too weak.":ambiguous?"Top placement candidates are too close.":"Highest confidence-weighted overlap.",scores); }
}
